import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (4,):
        raise ValueError(f"Expected input of shape (4,), got {x.shape}")

    quadratic = np.sum(x**2) + 0.2 * (x[0] * x[1] + x[2] * x[3])
    skewness = 0.5 / (1 + np.exp(-x[0]))

    return float(0.5 * quadratic + 0.5 * skewness)

import numpy as np

def problem(x: np.ndarray) -> float:
    if x.shape != (4,):
        raise ValueError("Input 'x' must be a 1D NumPy array of shape (4,).")

    quadratic_term = np.sum(x**2)
    skewed_term = (x[0] + 5)**3 * 0.05
    interaction_term = np.sum(x * np.roll(x, 1)) * 0.1

    result = quadratic_term + skewed_term + interaction_term
    return float(result)

import numpy as np

def problem(x: np.ndarray) -> float:
    quadratic_term = np.sum(x**2)
    skewed_term = (np.sum(x) + 2)**3 * 0.01
    return float(quadratic_term + skewed_term)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    if x.shape != (4,):
        raise ValueError("Input 'x' must be a 1D NumPy array of shape (4,).")

    # Quadratic component with hyperbolic tangents
    quadratic_term = np.sum(np.tanh(x)**2)

    # Skewed Power function of sum
    skewed_term = (np.sum(x) + 10)**3 * 0.3

    # Interaction term modulated by cosine
    interaction_term = (x[0] * x[1] + x[2] * x[3]) * np.cos(x[0] + x[3]);

    result = 0.7 * quadratic_term + 0.2 * skewed_term + 0.1 * interaction_term;
    return float(result)

import numpy as np
from scipy.special import j0

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    if x.shape != (4,):
        raise ValueError("Input 'x' must be a 1D NumPy array of shape (4,).")

    # Quadratic component
    quadratic_term = np.sum(x**2)

    # Skewed Power function of sum
    skewed_term = (np.sum(x) + 5)**3 * 0.2

    # Interaction term modulated by arctangent
    interaction_term = (np.arctan(x[0] * x[1]) + np.arctan(x[2] * x[3])) * 0.5;

    # Bessel modulated quadratic term
    distance_from_origin = np.sqrt(np.sum(x**2))
    bessel_mod = j0(distance_from_origin) * np.log(1 + distance_from_origin);
    bessel_term = quadratic_term * bessel_mod * 0.1

    result = 0.5 * quadratic_term + 0.2 * skewed_term + 0.2 * interaction_term + 0.1 * bessel_term;
    return float(result)
